typedef double (*func)(double);

double bisect(func f, double a, double b, double tol, int *steps) {
    double fa = f(a);
    *steps = 0;
    while (b - a > tol) {
        double m = (a + b) / 2;
        double fm = f(m);
        if (fa * fm <= 0) {
            b = m;
        } else {
            a = m;
            fa = fm;
        }
        (*steps)++;
    }
    return (a + b) / 2;
}

